import ast, os

def test_init():
    assert os.path.exists('vectorops/__init__.py')
    with open('vectorops/__init__.py') as f:
        code = f.read()
    local_dict = {}
    exec(compile(code, 'test', 'exec'), local_dict)
    assert local_dict['dotproduct']([1, 2], [3, 4]) == 11

def test_setup():
    assert os.path.exists('setup.py')
    with open('setup.py') as f:
        code = f.read()
    tree = ast.parse(code)
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and hasattr(node.func, 'id') and node.func.id == 'setup':
            for kw in node.keywords:
                if kw.arg == 'version' and isinstance(kw.value, ast.Constant):
                    assert kw.value.value == '0.1.0'


if __name__ == "__main__":
    test_init()
    test_setup()
